contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 dummy) public {
        require(dummy == dummy);
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        bool firstReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }
        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;
        bool secondReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondReverted = true; } else { secondReverted = false; }
        uint afterSecond = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(!firstReverted && !secondReverted && afterFirst == beforeMinSum && afterSecond == beforeMinSum);
    }
}

